contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint amount) public payable {
        require(address(this).balance >= amount);

        uint beforeC = address(c).balance;
        uint beforeThis = address(this).balance;

        bool reverted;
        try c.go{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(reverted || address(c).balance == 0);
        assert(reverted || address(this).balance == beforeThis - amount + beforeC);
        assert(reverted == (amount > address(this).balance));
    }

    receive() external payable {}
}

