contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint amount) public payable {
        require(address(this).balance >= amount);

        uint preCaller = address(this).balance;
        bool reverted;
        try c.go{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // The owner is the only address that can receive the swept balance.
        // If the caller is not the owner, the caller cannot receive anything back,
        // so a successful call cannot increase the caller's balance.
        address owner = c.owner();
        if (msg.sender != owner) {
            assert(reverted || address(this).balance <= preCaller);
        } else {
            assert(reverted || address(this).balance >= preCaller - amount);
        }
    }

    receive() external payable {}
}

